export function getEventImage(event: {
  id?: string;
  title?: string;
  summary?: string;
  imageUrl?: string;
  imageCaption?: string;
  imageSource?: string;
  date?: { day?: number; month?: number; year?: number };
}): HistoricalImageEntry | undefined {
  if (event.id && HISTORICAL_IMAGE_CATALOG[event.id]) {
    return HISTORICAL_IMAGE_CATALOG[event.id];
  }

  if (event.imageUrl) {
    return {
      eventId: event.id || "inline-event",
      imageUrl: event.imageUrl,
      imageCaption: event.imageCaption || event.title || "Tư liệu lịch sử",
      imageSource: event.imageSource || "Tư liệu lịch sử",
      referenceUrl: "https://david-lek.github.io/vietnamese-historical-events/",
    };
  }

  if (event.date?.day && event.date?.month && event.date?.year) {
    const key = `date-${event.date.day}-${event.date.month}-${event.date.year}`;
    if (HISTORICAL_IMAGE_CATALOG[key]) {
      return HISTORICAL_IMAGE_CATALOG[key];
    }
  }

  return undefined;
}

export function getPeriodImage(periodId: string): HistoricalImageEntry | undefined {
  return PERIOD_IMAGE_CATALOG[periodId];
}
